"""Independent reference implementations for stress testing (not submitted)."""
import itertools, random
from bisect import bisect_right

U = 1 << 128
WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def ref_runs(routes):
    """Naive boundary-sampling LPM compilation. routes: dict (start,len)->hop."""
    pts = {0, U}
    for (s, l) in routes:
        pts.add(s)
        pts.add(s + (1 << (128 - l)) if l else U)
    pts = sorted(pts)
    starts, hops = [], []
    for a, b in zip(pts, pts[1:]):
        if a == b:
            continue
        best = None
        for (s, l), h in routes.items():
            e = s + (1 << (128 - l)) if l else U
            if s <= a < e and (best is None or l > best[0]):
                best = (l, h)
        hop = None if best is None else best[1]
        if hops and hops[-1] == hop:
            continue
        starts.append(a)
        hops.append(hop)
    if not starts:
        return [0], [None]
    return starts, hops


def ref_changes(old, new):
    (sa, ha), (sb, hb) = old, new
    pts = sorted(set(sa) | set(sb) | {U})
    rows = []
    for a, b in zip(pts, pts[1:]):
        x = ha[bisect_right(sa, a) - 1]
        y = hb[bisect_right(sb, a) - 1]
        if x != y:
            if rows and rows[-1][1] == a and rows[-1][2] == x and rows[-1][3] == y:
                rows[-1][1] = b
            else:
                rows.append([a, b, x, y])
    return rows


def _pages(used):
    return (used + 63) // 64


def _trees(lo, span):
    """All legal ordered trees covering [lo, lo+span) as nested tuples."""
    out = []
    if span <= 8:
        out.append(("leaf", lo, span, ()))
    if span >= 2:
        for m in range(2, min(9, span) + 1):
            for cuts in itertools.combinations(range(lo + 1, lo + span), m - 1):
                bounds = (lo,) + cuts + (lo + span,)
                kids = []
                ok = True
                for a, b in zip(bounds, bounds[1:]):
                    sub = _trees(a, b - a)
                    if not sub:
                        ok = False
                        break
                    kids.append(sub)
                if not ok:
                    continue
                for combo in itertools.product(*kids):
                    out.append(("node", lo, span, combo))
    return out


def brute_frontier(R, starts, q, bursts, cap, hit, miss, decode):
    """Exact (work, pages) frontier by exhaustive enumeration; small R only."""
    qsum = [0] * (R + 1)
    for i in range(R):
        qsum[i + 1] = qsum[i] + q[i]
    T = [[0] * (R + 1) for _ in range(R + 1)]
    for i in range(R):
        for j in range(i + 1, R + 1):
            t = 0
            for w, runs in bursts:
                if any(i <= r < j for r in runs):
                    t += w
            T[i][j] = t
    frontier = [(1 << 60, 1 << 60)] * (cap + 1)

    def allowed(i, j):
        spread = starts[j - 1] - starts[i]
        modes = [0]
        if spread < (1 << 64):
            modes.append(1)
        if spread < (1 << 32):
            modes.append(2)
        return modes

    def enumerate_tree(tree):
        """Yield (list of node dicts) over all mode assignments."""
        kind, lo, span, kids = tree
        modes = allowed(lo, lo + span)
        if kind == "leaf":
            for mode in modes:
                yield [(1, mode, lo, span, 0)]
        else:
            m = len(kids)
            rest = list(itertools.product(*[list(enumerate_tree(k)) for k in kids]))
            for mode in modes:
                for combo in rest:
                    yield [(0, mode, lo, span, m)] + [n for part in combo for n in part]

    for tree in _trees(0, R):
        for nodes in enumerate_tree(tree):
            # knapsack over the nodes of this layout
            base = 0
            items = []
            for kind, mode, lo, span, m in nodes:
                if kind:
                    used = 32 + span * WIDTH[mode]
                    keys = span
                else:
                    used = 32 + 4 * m + (m - 1) * WIDTH[mode]
                    keys = m - 1
                p = _pages(used)
                b = (keys + LANES[mode] - 1) // LANES[mode] + decode[mode]
                t = T[lo][lo + span]
                qq = qsum[lo + span] - qsum[lo]
                base += p * miss * t + b * qq
                items.append((p, p * (miss - hit) * t))
            best = [(base, 0)] * (cap + 1)
            reach = [0] * (cap + 1)
            for p, gain in items:
                for c in range(cap, p - 1, -1):
                    if reach[c - p] + 1 > 0:
                        cand = best[c - p][0] - gain
                        if cand < best[c][0]:
                            best[c] = (cand, 0)
                            reach[c] = reach[c - p] + 1
                for c in range(1, cap + 1):
                    if best[c - 1][0] < best[c][0]:
                        best[c] = best[c - 1]
            total_pages = sum(_pages(32 + span * WIDTH[mode]) if kind else
                              _pages(32 + 4 * m + (m - 1) * WIDTH[mode])
                              for kind, mode, lo, span, m in nodes)
            for c in range(cap + 1):
                if (best[c][0], total_pages) < frontier[c]:
                    frontier[c] = (best[c][0], total_pages)
    return frontier


def brute_objective(versions, per_version_q, per_version_bursts, cap, hit, miss, decode):
    fronts = [brute_frontier(len(v[0]), v[0], per_version_q[i], per_version_bursts[i],
                             cap, hit, miss, decode) for i, v in enumerate(versions)]
    best = None
    n = len(versions)
    for alloc in itertools.product(*[range(cap + 1)] * n):
        if sum(alloc) > cap:
            continue
        work = sum(fronts[i][alloc[i]][0] for i in range(n))
        pages = sum(fronts[i][alloc[i]][1] for i in range(n))
        if best is None or (work, pages) < best:
            best = (work, pages)
    return best
